using System.Text;

namespace AiNexus.Generators.Common;

/// <summary>以四個空白縮排寫出產生的原始碼；每個產生檔都以 <see cref="Header"/> 開頭。</summary>
internal sealed class SourceWriter
{
    /// <summary>標成 auto-generated，分析器與程式碼樣式規則才不檢查；nullable 要另外開，因為產生檔不繼承專案設定。</summary>
    public const string Header = "// <auto-generated/>\n#nullable enable\n";

    private readonly StringBuilder text = new(Header);
    private int depth;

    public SourceWriter Line(string line = "")
    {
        if (line.Length > 0) text.Append(' ', depth * 4).Append(line);
        text.Append('\n');
        return this;
    }

    /// <summary>寫出 <paramref name="line"/> 與左大括號，之後的內容多縮一層，直到 <see cref="Close"/>。</summary>
    public SourceWriter Open(string line)
    {
        Line(line).Line("{");
        depth++;
        return this;
    }

    public SourceWriter Close()
    {
        depth--;
        return Line("}");
    }

    public override string ToString() => text.ToString();
}
